"use strict";
import { PositionStatus } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { Trans } from "react-i18next";
import { Flex, Text, useSporeColors } from "ui/src";
import { Shrink } from "ui/src/components/icons";
import { formatCurrencyAmount } from "utils/formatCurrencyAmount";
import TokenDetails from "./TokenDetails";
import PositionRow from "./PositionRow";
const CurrencyDetails = ({
  position,
  isV3,
  getStatusColor
}) => <Flex row $md={{ flexDirection: "column", alignItems: "flex-start" }} gap={"$gap12"} alignItems="center">
    <Text variant="body4" color={"$neutral2"}>
      {formatCurrencyAmount(position.currency0Amount, 4)} {position.currency0Amount?.currency.symbol} +{" "}
      {formatCurrencyAmount(position.currency1Amount, 4)} {position.currency1Amount?.currency.symbol}
    </Text>

    <Flex row gap={"$gap8"} alignItems="center">
      {isV3 ? <>
          <Shrink size={18} color={getStatusColor()} />
          <Text variant="buttonLabel4" color={getStatusColor()}>
            {position?.status === PositionStatus.IN_RANGE ? <Trans i18nKey="common.withinRange" /> : position?.status === PositionStatus.OUT_OF_RANGE ? <Trans i18nKey="common.outOfRange" /> : "Unknown"}
          </Text>
        </> : <>
          <Shrink size={18} color={getStatusColor()} />
          <Text variant="buttonLabel4" color={getStatusColor()}>
            <Trans i18nKey="common.withinRange" />
          </Text>
        </>}
    </Flex>
  </Flex>;
export default function PoolLiquidityRewards({ poolGroup, isLoading }) {
  const colors = useSporeColors();
  if (isLoading) {
    return <Flex flexDirection="column" gap={"$gap12"}>
        <Flex
      style={{
        background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
      }}
      py={"$spacing24"}
      px={"$spacing20"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      opacity={0.6}
    >
          <Flex row gap={"$gap12"} justifyContent="space-between">
            <TokenDetails isLoading={true} />
            <Flex flexDirection="column" gap={"$gap12"} justifyContent="center" alignItems="flex-end">
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Text variant="body3" fontSize={"$mdall"}>
                -
              </Text>
            </Flex>
          </Flex>
        </Flex>
      </Flex>;
  }
  if (!poolGroup) {
    return null;
  }
  const totalValue = "-";
  const token0Symbol = poolGroup.representative.currency0Amount?.currency.symbol || "";
  const token1Symbol = poolGroup.representative.currency1Amount?.currency.symbol || "";
  let totalToken0Amount = poolGroup.positions.reduce((sum, pos) => {
    return sum + parseFloat(formatCurrencyAmount(pos.currency0Amount, 6) || "0");
  }, 0);
  let totalToken1Amount = poolGroup.positions.reduce((sum, pos) => {
    return sum + parseFloat(formatCurrencyAmount(pos.currency1Amount, 6) || "0");
  }, 0);
  return <Flex flexDirection="column" gap={"$gap12"}>
      {
    /* Pool Header - shown once */
  }
      <Flex
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
    py={"$spacing24"}
    px={"$spacing20"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    hoverStyle={{ borderColor: "$surface3Hovered" }}
  >
        <Flex
    row
    gap={"$gap12"}
    justifyContent="space-between"
    $md={{ flexDirection: "column", justifyContent: "flex-start" }}
  >
          <TokenDetails position={poolGroup.representative} />

          <Flex flexDirection="column" gap={"$gap24"} width={"unset"} $md={{ width: "100%" }}>
            <Flex
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $md={{ row: true, justifyContent: "space-between", mt: "$gap12" }}
  >
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Flex flexDirection="column" alignItems="flex-end" gap={"$gap4"} $md={{ alignItems: "flex-start" }}>
                <Text variant="body3" fontSize={"$mdall"}>
                  {totalValue}
                </Text>
                <Text variant="body4" color={"$neutral2"}>
                  {totalToken0Amount.toFixed(4)} {token0Symbol}, {totalToken1Amount.toFixed(4)} {token1Symbol}
                </Text>
              </Flex>
            </Flex>

          </Flex>
        </Flex>
      </Flex>

      {
    /* Individual Positions */
  }
      {poolGroup.positions.map((position, index) => <Flex key={`${poolGroup.poolKey}-${index}`}>
          <PositionRow index={index} position={position} CurrencyDetails={CurrencyDetails} />
        </Flex>)}
    </Flex>;
}
